
.form {
  width: 100%;
  max-width: 560px;
  margin: 0 auto;
  padding: 14px;
  border: 1px solid var(--c-border);
  background-color: var(--c-surface);
  box-shadow: 2px 2px 0 rgb(51 48 42 / 12%);
}

.head {
  padding-bottom: 9px;
  margin-bottom: 12px;
  border-bottom: 1px solid var(--c-border);
}

.title {
  margin: 0;
  font-size: 17px;
  letter-spacing: 0.1em;
}

.sub {
  margin: 4px 0 0;
  font-size: 12px;
  color: var(--c-muted);
}

.field {
  margin-bottom: 12px;
}

.label {
  margin-bottom: 5px;
  font-size: 12px;
  font-weight: 600;
}

.input {
  box-sizing: border-box;
  width: 100%;
  padding: 5px 8px;
  font-family: inherit;
  font-size: 13px;
  color: var(--c-text);
  background-color: var(--c-surface-sunken);
  border: 1px solid var(--c-border);

  &:focus {
    border-color: var(--c-accent);
    outline: none;
  }
}

.area {
  resize: vertical;
}

.chips {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
}

.chip {
  padding: 3px 10px;
  font-family: inherit;
  font-size: 12px;
  color: var(--c-text);
  cursor: pointer;
  background-color: var(--c-surface-sunken);
  border: 1px solid var(--c-border);

  &.on {
    color: var(--c-surface);
    background-color: var(--c-accent);
    border-color: var(--c-accent);
  }
}

.starts {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.start {
  display: flex;
  align-items: baseline;
  gap: 9px;
  padding: 6px 10px;
  font-family: inherit;
  text-align: left;
  cursor: pointer;
  background-color: var(--c-surface-sunken);
  border: 1px solid var(--c-border);

  &.on {
    border-color: var(--c-accent);
    box-shadow: inset 3px 0 0 var(--c-accent);
  }
}

.start-label {
  flex: 0 0 auto;
  font-size: 13px;
  font-weight: 700;
  color: var(--c-text);
}

.start-desc {
  flex: 1 1 auto;
  font-size: 11px;
  color: var(--c-muted);
}

.submit {
  width: 100%;
  padding: 8px;
  margin-top: 3px;
  font-family: inherit;
  font-size: 14px;
  font-weight: 700;
  letter-spacing: 0.2em;
  color: var(--c-surface);
  cursor: pointer;
  background-color: var(--c-accent);
  border: 1px solid var(--c-accent);

  &:disabled {
    color: var(--c-muted);
    cursor: not-allowed;
    background-color: var(--c-track);
    border-color: var(--c-border);
  }
}
